def compare(stock: Stock, counts: dict[str, int]) -> list[Discrepancy]:
    return sorted((Discrepancy(sku, stock.available(sku), n) for sku, n in counts.items()
                   if stock.available(sku) != n), key=lambda d: d.sku)

